// New synthesized soundtrack and radio. No original recordings or old audio module.
window.RadioAudio=(()=>{
 let ctx,bus,musicBus,step=0,next=0,timer,lang='de',enabled=true,speaking=false,queue=[];
 const levels={music:0.5,effects:0.7,voice:0.9};
 const lines={capture:['Sektor gesichert.','Territory secured.'],lost:['Wir verlieren ein Gebiet.','Territory lost.'],ready:['Verstärkung einsatzbereit.','Reinforcements ready.'],crewed:['Fahrzeug übernommen.','Vehicle crewed.'],grenades:['Munition aufgenommen.','Ammunition collected.'],victory:['Schlacht gewonnen.','Battle won.'],defeat:['Fort verloren. Rückzug.','Fort lost. Retreat.'],start:['Einheiten bereit. Sichert die Fabriken.','Units ready. Secure the factories.']};
 function boot(){if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();bus=ctx.createGain();bus.connect(ctx.destination);musicBus=ctx.createGain();musicBus.connect(bus);mix();}if(ctx.state==='suspended')ctx.resume();if(!timer){next=ctx.currentTime+.05;timer=setInterval(schedule,90);}return ctx;}
 function mix(){if(!ctx)return;bus.gain.setTargetAtTime(enabled?.6:0,ctx.currentTime,.05);musicBus.gain.setTargetAtTime(levels.music*(speaking?.12:.45),ctx.currentTime,.15);}
 function note(freq,t,dur,vol,type='triangle',dest=musicBus){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0001,vol),t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(dest);o.start(t);o.stop(t+dur+.02);}
 function schedule(){if(!ctx||ctx.state!=='running')return;if(next<ctx.currentTime-.2)next=ctx.currentTime+.02;while(next<ctx.currentTime+.2){const i=step%16,bar=Math.floor(step/16)%8,roots=[40,40,36,38,40,43,36,38],root=roots[bar],f=n=>440*2**((n-69)/12);if(i%2===0)note(f(root-12+(i===10?7:0)),next,.22,.18,'sawtooth');if(i===0||i===8)note(90,next,.15,.4,'sine');if(i===4||i===12){note(190,next,.08,.13,'triangle');note(3800,next,.04,.025,'square');}if(i%2===1)note(7800,next,.025,.025,'square');if(bar>1&&i%4===2)note(f(root+24+[0,7,10,12][i>>2]),next,.35,.09);if(i===0)for(const n of [0,7,12])note(f(root+n),next,1.7,.045,'sine');step++;next+=60/116/4;}}
 function nextLine(){if(speaking||!queue.length||!window.speechSynthesis)return;const text=queue.shift(),u=new SpeechSynthesisUtterance(text);u.lang=lang==='de'?'de-DE':'en-US';u.pitch=.75;u.rate=1.05;u.volume=levels.voice;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang.startsWith(lang))||null;speaking=true;mix();let finished=false;const done=()=>{if(finished)return;finished=true;clearTimeout(watch);speaking=false;mix();nextLine();};const watch=setTimeout(done,Math.max(4500,text.length*130));u.onend=done;u.onerror=done;speechSynthesis.speak(u);}
 const recent=new Map();
 return {unlock:boot,setLanguage(v){lang=v;},set(k,v){levels[k]=Math.max(0,Math.min(1,+v));mix();},mute(v){enabled=!v;mix();if(v&&window.speechSynthesis){queue=[];speechSynthesis.cancel();}},say(k){const words=lines[k];if(!words)return;const text=words[lang==='de'?0:1];window.dispatchEvent(new CustomEvent('radio',{detail:text}));if(!enabled||levels.voice===0||Date.now()-(recent.get(k)||0)<3000)return;recent.set(k,Date.now());queue.push(text);if(queue.length>3)queue.shift();nextLine();},effect(k){if(!enabled)return;boot();const t=ctx.currentTime;if(k==='shot')note(270,t,.05,levels.effects*.08,'square',bus);else note(75,t,.35,levels.effects*.25,'sawtooth',bus);}};
})();
